  "CREATE VIEW vw_CategoryStats AS\nSELECT c.CategoryName,\n       COUNT(*) AS ProductCount,\n       AVG(p.UnitPrice) AS AvgPrice\nFROM Categories c\nINNER JOIN Products p ON p.CategoryID = c.CategoryID\nGROUP BY c.CategoryName;",
