  "CREATE VIEW vw_CheapProducts AS\nSELECT ProductID, ProductName, UnitPrice\nFROM Products\nWHERE UnitPrice < 10\nWITH CHECK OPTION;\nGO\nUPDATE vw_CheapProducts\nSET UnitPrice = 15\nWHERE ProductID = 13;   -- נכשל",
