 ('מחיקה', 'מחקו את כל הפרוצדורות שיצרתם בתרגיל.',
  "DROP PROCEDURE usp_GetEmployees, usp_CustomersByCountry, usp_ProductsInPriceRange,\n               usp_CountProducts, usp_CustomerExists, usp_AddShipper, usp_RaisePrice;", ''),
