INTRO = {
 '7': 'הריצו כל שאלה בתוך BEGIN TRANSACTION … ROLLBACK, כך שמסד Northwind יחזור למצבו המקורי.',
 '8': 'התרגיל נעשה במסד תרגול נפרד (SchoolPractice), כדי לא לשנות את Northwind.',
 '9': 'כל ה-Views נוצרים במסד Northwind, ובסוף התרגיל מוחקים אותם.',
 '10': 'כל הפרוצדורות נוצרות במסד Northwind, ובסוף התרגיל מוחקים אותן. שינויים בנתונים נבדקים בתוך טרנזקציה.',
}
for k, title, items in (('7', 'טיפול בנתונים', E7), ('8', 'פקודות DDL', E8), ('9', 'Views', E9), ('10', 'Stored Procedures', E10)):
    ex[k] = {'title': title, 'intro': INTRO[k], 'items': [{'sec': s, 'q': q, 'a': a, 'fixed': '', 'note': n} for s, q, a, n in items]}
json.dump(ex, open(P, 'w'), ensure_ascii=False, indent=1)
print({k: len(v['items']) for k, v in ex.items()})
